char *read_next_line(FILE *VFile, char *ptr) {
    if (!VFile || !ptr) {
        return NULL;
    }

    if (fgets(ptr, 256, VFile) == NULL) {
        return NULL;
    }

    // Remove trailing newline character if present
    size_t len = strlen(ptr);
    if (len > 0 && ptr[len - 1] == '\n') {
        ptr[len - 1] = '\0';
    }

    return ptr;
}
